files.content:
:root {
  --bg: #fbfaf8;
  --surface: #ffffff;
  --text: #201c17;
  --muted: #6b6255;
  --accent: #7c5cff;
  --border: #e6e1d8;
  --bad: #c92a2a;
  --bad-bg: #fbe1e1;
  --good: #2f9e44;
  --good-bg: #e0f5e4;
  --radius: 10px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #17140f;
    --surface: #201c17;
    --text: #f2ede4;
    --muted: #a89d8c;
    --accent: #a68bff;
    --border: #362f26;
    --bad: #ff8787;
    --bad-bg: #3a2323;
    --good: #69db7c;
    --good-bg: #1f3a25;
  }
}

* { box-sizing: border-box; }
body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: var(--bg); color: var(--text); }
.wrap { max-width: 480px; margin: 0 auto; padding: 2.5rem 1.5rem 4rem; }

.tag { display: inline-block; font-weight: 700; padding: 0.25rem 0.6rem; border-radius: 999px; background: var(--bad-bg); color: var(--bad); margin-bottom: 0.75rem; }
.tag.good { background: var(--good-bg); color: var(--good); }

h1 { margin-top: 0; }

.carousel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 1.5rem; position: relative; }
.slide { min-height: 3.5rem; font-size: 1.05rem; line-height: 1.5; }
.sr-status { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

.controls { display: flex; gap: 0.75rem; margin-top: 1rem; }
.controls .btn, .controls button {
  font: inherit;
  padding: 0.5rem 1rem;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text);
  cursor: pointer;
}
.controls button:hover, .controls .btn:hover { border-color: var(--accent); }
.controls button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.dots { display: flex; gap: 0.4rem; margin-top: 1rem; }
.dots button { width: 0.6rem; height: 0.6rem; padding: 0; border-radius: 50%; border: none; background: var(--border); cursor: pointer; }
.dots button[aria-current="true"] { background: var(--accent); }
.dots button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

a { color: var(--accent); }
